/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

M2C_UNK playMusicStream();                            /* extern */
f32 readRomTableScaledValue(s32);                             /* extern */
M2C_UNK spawnWrappedCaptions(s32, M2C_UNK *, M2C_UNK, M2C_UNK, f32, s32); /* extern */
M2C_UNK loadTextString(M2C_UNK *, s32);              /* extern */
extern s32 gSceneState;

/* Starts the music stream, then loads text textId and shows it as wrapped captions with its timing value from the ROM table. */ void showCutsceneCaption(s32 textId) {
    char text[0x200];
    f32 duration;

    playMusicStream();
    duration = readRomTableScaledValue(textId);
    loadTextString(text, textId);
    spawnWrappedCaptions(gSceneState, text, 0x20, 2, duration, 4);
}
